type wrappedTenantScope struct {
	raw string
}

type wrappedTenantCodec struct {
	p *wrappedTenantScope
}

func (c *wrappedTenantCodec) Scan(src any) error {
	switch v := src.(type) {
	case string:
		c.p.raw = v
		return nil
	case []byte:
		c.p.raw = string(v)
		return nil
	default:
		return fmt.Errorf("cannot scan %T into wrappedTenantScope", src)
	}
}

func (c *wrappedTenantCodec) Value() (driver.Value, error) {
	return c.p.raw, nil
}

func TestSharedTableRowTagsAndScopeWrapDualDriver(t *testing.T) {
	dsn := os.Getenv("TABULA_TEST_DSN")
	require.NotEmpty(t, dsn, "TABULA_TEST_DSN is required for integration tests")
	ctx := t.Context()

	db, err := sql.Open("postgres", dsn)
	require.NoError(t, err)
	t.Cleanup(func() { require.NoError(t, db.Close()) })

	pool, err := pgxpool.New(ctx, dsn)
	require.NoError(t, err)
	t.Cleanup(pool.Close)

	suffix := time.Now().UnixNano()
	schema := fmt.Sprintf("tabula_shared_%d", suffix)
	appRole := fmt.Sprintf("tabula_shared_app_%d", suffix)

	exec := func(q string) {
		t.Helper()
		_, err := db.ExecContext(ctx, q)
		require.NoError(t, err, q)
	}
	exec("CREATE ROLE " + appRole + " NOLOGIN NOBYPASSRLS")
	t.Cleanup(func() { _, _ = db.Exec("DROP ROLE IF EXISTS " + appRole) })
	exec("CREATE SCHEMA " + schema)
	t.Cleanup(func() { _, _ = db.Exec("DROP SCHEMA IF EXISTS " + schema + " CASCADE") })

	itemsTable := schema + ".items"
	exec(`CREATE TABLE ` + itemsTable + ` (
		id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		scope_id uuid NOT NULL,
		code text NOT NULL,
		name text NOT NULL,
		version integer NOT NULL DEFAULT 1,
		deleted_at timestamptz,
		note text,
		tags text[] NOT NULL DEFAULT '{}',
		meta jsonb NOT NULL DEFAULT '{}'::jsonb,
		created_at timestamptz NOT NULL DEFAULT now()
	)`)
	exec("GRANT USAGE ON SCHEMA " + schema + " TO " + appRole)
	exec("GRANT SELECT, INSERT, UPDATE ON " + itemsTable + " TO " + appRole)
	exec("ALTER TABLE " + itemsTable + " ENABLE ROW LEVEL SECURITY")
	exec("ALTER TABLE " + itemsTable + " FORCE ROW LEVEL SECURITY")
	exec("CREATE POLICY items_scope ON " + itemsTable + " FOR ALL TO " + appRole +
		" USING (scope_id = nullif(current_setting('demo.scope', true), '')::uuid)" +
		" WITH CHECK (scope_id = nullif(current_setting('demo.scope', true), '')::uuid)")

	type auditFields struct {
		CreatedAt time.Time `db:"created_at,once"`
	}
	type sharedItem struct {
		ID        int64              `db:"id,key,serial"`
		ScopeID   wrappedTenantScope `db:"scope_id,scope"`
		Code      string             `db:"code,once"`
		Name      string             `db:"name"`
		Version   int                `db:"version,version"`
		DeletedAt *time.Time         `db:"deleted_at,deleted"`
		Note      string             `db:"note,once,zero"`
		Tags      []string           `db:"tags,once,array"`
		Meta      map[string]any     `db:"meta,once,json"`
		auditFields
	}
	type sharedItemListRow struct {
		sharedItem
		Extra *string `db:"extra"`
	}
	type codeArgs struct {
		Code string `db:"code"`
	}
	type insertArgs struct {
		Code string         `db:"code"`
		Name string         `db:"name"`
		Note *string        `db:"note"`
		Tags []string       `db:"tags,array"`
		Meta map[string]any `db:"meta,json"`
	}
	type listArgs struct {
		Code *string `db:"code"`
	}

	const selectCols = "id, scope_id, code, name, version, deleted_at, note, tags, meta, created_at"

	for _, driverName := range []string{"stdsql", "pgxdriver"} {
		t.Run(driverName, func(t *testing.T) {
			key := tabula.NewSessionKey()
			cfg := tabula.RegistryConfig[wrappedTenantScope]{
				SessionKey: key,
				Deny:       tabula.DenyLegacySQL | tabula.DenyDelete,
				ScopeID:    func(s wrappedTenantScope) any { return s.raw },
				ScopeWrap:  func(p *wrappedTenantScope) any { return &wrappedTenantCodec{p: p} },
				TypeFamilies: []tabula.TypeFamily{
					tabula.TypeFamilyOf[wrappedTenantScope]("uuid"),
				},
			}
			if driverName == "stdsql" {
				cfg.ArrayArg = pqdriver.Array
				cfg.ArrayColumn = pqdriver.ArrayColumn
			} else {
				cfg.ArrayColumn = pgxdriver.ArrayColumn
			}
			reg := tabula.NewRegistry(cfg)

			items := tabula.Define(reg, tabula.TableSpec[sharedItem, int64]{
				Name: itemsTable,
			})
			qByCode := tabula.DefineSQL[sharedItem, codeArgs](reg, tabula.SQLSpec{
				Name:  "items.by_code",
				SQL:   "SELECT " + selectCols + " FROM " + itemsTable + " WHERE scope_id = @scope_id AND code = @code AND deleted_at IS NULL",
				Scope: tabula.ScopeParam("scope_id"),
			})
			qInsert := tabula.DefineSQLReturning[sharedItem, insertArgs](reg, tabula.SQLSpec{
				Name: "items.insert_returning",
				SQL: "INSERT INTO " + itemsTable + " (scope_id, code, name, note, tags, meta) " +
					"VALUES (@scope_id, @code, @name, @note, @tags, @meta) RETURNING " + selectCols,
				Scope: tabula.ScopeParam("scope_id"),
			})
			qList := tabula.DefineSQLList[sharedItemListRow, listArgs](reg, tabula.SQLListSpec{
				Name:      "items.list",
				Select:    "SELECT " + selectCols + ", code || ':' || name AS extra FROM " + itemsTable,
				Where:     "scope_id = @scope_id AND deleted_at IS NULL",
				CountBase: "SELECT count(*) FROM " + itemsTable,
				Scope:     tabula.ScopeParam("scope_id"),
				Filters: []tabula.SQLFilter{
					{Name: "code", SQL: "code = @code"},
				},
				Order: tabula.QueryOrderSpec{
					Default:          "id",
					DefaultDirection: tabula.SortAsc,
					Sorts: []tabula.QuerySort{
						{Key: "id", Expr: "id", Column: "id"},
						{Key: "scope", Expr: "scope_id", Column: "scope_id"},
					},
					TieBreaker: []tabula.QuerySortTerm{{Expr: "id", Column: "id"}},
				},
				MaxLimit: 20,
				Keyset:   true,
			})

			// Non-executing catalog verification over both Define table and DefineSQL* views.
			defs := append(reg.Defined(), sqlcheck.ViewsToDefinitions(reg.DefinedViews())...)
			findings, err := sqlcheck.VerifyStatementsUsing(ctx, pgxdriver.SQLVerifier(pool), defs, appRole)
			require.NoError(t, err)
			require.Empty(t, findings)

			var runTx func(scope wrappedTenantScope, ro bool, fn func(context.Context, tabula.Session[wrappedTenantScope]) error) error
			if driverName == "stdsql" {
				runner, err := stdsql.NewRunner(db, stdsql.ScopePolicy[wrappedTenantScope]{
					ManagedVars: []string{"demo.scope"},
					ScopeVars:   func(s wrappedTenantScope) map[string]string { return map[string]string{"demo.scope": s.raw} },
				}, stdsql.RunnerOptions{
					Role:         appRole,
					SessionKey:   key,
					SQLAuthority: reg.SQLAuthority(),
				})
				require.NoError(t, err)
				runTx = func(scope wrappedTenantScope, ro bool, fn func(context.Context, tabula.Session[wrappedTenantScope]) error) error {
					if ro {
						return runner.WithinReadOnly(ctx, scope, func(c context.Context, s *stdsql.Session[wrappedTenantScope]) error { return fn(c, s) })
					}
					return runner.Within(ctx, scope, func(c context.Context, s *stdsql.Session[wrappedTenantScope]) error { return fn(c, s) })
				}
			} else {
				runner, err := pgxdriver.NewRunner(pool, pgxdriver.ScopePolicy[wrappedTenantScope]{
					ManagedVars: []string{"demo.scope"},
					ScopeVars:   func(s wrappedTenantScope) map[string]string { return map[string]string{"demo.scope": s.raw} },
				}, pgxdriver.RunnerOptions{
					Role:         appRole,
					SessionKey:   key,
					SQLAuthority: reg.SQLAuthority(),
				})
				require.NoError(t, err)
				runTx = func(scope wrappedTenantScope, ro bool, fn func(context.Context, tabula.Session[wrappedTenantScope]) error) error {
					if ro {
						return runner.WithinReadOnly(ctx, scope, func(c context.Context, s *pgxdriver.Session[wrappedTenantScope]) error { return fn(c, s) })
					}
					return runner.Within(ctx, scope, func(c context.Context, s *pgxdriver.Session[wrappedTenantScope]) error { return fn(c, s) })
				}
			}

			scopeA := wrappedTenantScope{raw: "11111111-1111-4111-8111-111111111111"}
			if driverName == "pgxdriver" {
				scopeA = wrappedTenantScope{raw: "22222222-2222-4222-8222-222222222222"}
			}
			now := time.Now().UTC().Truncate(time.Microsecond)

			var firstID, secondID int64
			require.NoError(t, runTx(scopeA, false, func(c context.Context, s tabula.Session[wrappedTenantScope]) error {
				// 1. Insert via Define table using sharedItem, then update via Save (optimistic version).
				row := sharedItem{
					ScopeID:     scopeA,
					Code:        "A-1",
					Name:        "Alpha",
					Version:     1,
					Note:        "",
					Tags:        []string{"green"},
					Meta:        map[string]any{"stage": "one"},
					auditFields: auditFields{CreatedAt: now},
				}
				require.NoError(t, items.Bind(s).Insert(c, &row))
				firstID = row.ID
				require.Positive(t, firstID)

				gotTable, err := items.Bind(s).Get(c, firstID)
				require.NoError(t, err)
				require.NotNil(t, gotTable)
				require.Equal(t, scopeA, gotTable.ScopeID)
				require.Equal(t, 1, gotTable.Version)

				gotTable.Name = "Alpha-V2"
				gotTable.Version++
				require.NoError(t, items.Bind(s).Save(c, *gotTable))

				// 2. Insert second row via DefineSQLReturning using the same sharedItem struct.
				note := "second-note"
				created, err := qInsert.Bind(s).One(c, insertArgs{
					Code: "B-2",
					Name: "Beta",
					Note: &note,
					Tags: []string{"blue", "gold"},
					Meta: map[string]any{"stage": "two"},
				})
				require.NoError(t, err)
				secondID = created.ID
				require.Equal(t, scopeA, created.ScopeID)
				require.Equal(t, "B-2", created.Code)
				require.Equal(t, "second-note", created.Note)
				require.Equal(t, []string{"blue", "gold"}, created.Tags)
				require.Equal(t, map[string]any{"stage": "two"}, created.Meta)
				require.Equal(t, 1, created.Version)
				return nil
			}))

			require.NoError(t, runTx(scopeA, true, func(c context.Context, s tabula.Session[wrappedTenantScope]) error {
				// 3. Read via DefineSQL into the same sharedItem struct.
				byCode, err := qByCode.Bind(s).One(c, codeArgs{Code: "A-1"})
				require.NoError(t, err)
				require.Equal(t, firstID, byCode.ID)
				require.Equal(t, scopeA, byCode.ScopeID)
				require.Equal(t, "Alpha-V2", byCode.Name)
				require.Equal(t, 2, byCode.Version)
				require.Equal(t, []string{"green"}, byCode.Tags)
				require.Equal(t, map[string]any{"stage": "one"}, byCode.Meta)

				// 4. List + keyset pagination via DefineSQLList into anonymously embedded sharedItemListRow.
				rows, total, err := qList.Bind(s).List(c, listArgs{}, tabula.QueryPage{Sort: "id", Direction: tabula.SortAsc, Size: 10})
				require.NoError(t, err)
				require.Equal(t, int64(2), total)
				require.Len(t, rows, 2)
				require.Equal(t, firstID, rows[0].ID)
				require.Equal(t, scopeA, rows[0].ScopeID)
				require.NotNil(t, rows[0].Extra)
				require.Equal(t, "A-1:Alpha-V2", *rows[0].Extra)

				p1, err := qList.Bind(s).ListKeyset(c, listArgs{}, tabula.QueryKeyset{Sort: "scope", Direction: tabula.SortAsc, Limit: 1})
				require.NoError(t, err)
				require.True(t, p1.HasMore)
				require.Len(t, p1.Items, 1)
				require.Equal(t, firstID, p1.Items[0].ID)

				p2, err := qList.Bind(s).ListKeyset(c, listArgs{}, tabula.QueryKeyset{Sort: "scope", Direction: tabula.SortAsc, Limit: 1, After: p1.Next})
				require.NoError(t, err)
				require.False(t, p2.HasMore)
				require.Len(t, p2.Items, 1)
				require.Equal(t, secondID, p2.Items[0].ID)
				require.Equal(t, scopeA, p2.Items[0].ScopeID)
				require.NotNil(t, p2.Items[0].Extra)
				require.Equal(t, "B-2:Beta", *p2.Items[0].Extra)
				return nil
			}))
		})
	}
}

func TestChoosingAnAPIGuideStarter(t *testing.T) {
	dsn := os.Getenv("TABULA_TEST_DSN")
	require.NotEmpty(t, dsn, "TABULA_TEST_DSN is required for integration tests")
	ctx := t.Context()

	repo, err := filepath.Abs("../..")
	require.NoError(t, err)
	guide, err := os.ReadFile(filepath.Join(repo, "docs", "CHOOSING-AN-API.md"))
	require.NoError(t, err)

	block := regexp.MustCompile("(?ms)```go\n(package db\n.*?)\n```").FindSubmatch(guide)
	require.Len(t, block, 2, "missing package db starter block in docs/CHOOSING-AN-API.md")
	starterSrc := string(block[1])

	// Extract pgx/v5 version from pgxdriver/go.mod so temp builds stay fully offline.
	pgxModBytes, err := os.ReadFile(filepath.Join(repo, "pgxdriver", "go.mod"))
	require.NoError(t, err)
	pgxVerMatch := regexp.MustCompile(`github\.com/jackc/pgx/v5\s+(v[^\s]+)`).FindSubmatch(pgxModBytes)
	require.Len(t, pgxVerMatch, 2, "cannot determine pgx/v5 version from pgxdriver/go.mod")
	pgxVersion := string(pgxVerMatch[1])

	// 1. Compile the unmodified starter block verbatim to prevent documentation drift.
	compileDir := t.TempDir()
	require.NoError(t, os.MkdirAll(filepath.Join(compileDir, "db"), 0o700))
	require.NoError(t, os.WriteFile(filepath.Join(compileDir, "db", "db.go"), []byte(starterSrc), 0o600))
	require.NoError(t, os.WriteFile(filepath.Join(compileDir, "go.mod"), []byte(fmt.Sprintf(
		"module example.org/choosingapi\n\ngo 1.26.0\n\nrequire (\n\tgithub.com/0xJean/tabula v0.0.0\n\tgithub.com/0xJean/tabula/pgxdriver v0.0.0\n\tgithub.com/jackc/pgx/v5 %s\n)\n\nreplace (\n\tgithub.com/0xJean/tabula => %q\n\tgithub.com/0xJean/tabula/pgxdriver => %q\n)\n",
		pgxVersion, filepath.ToSlash(repo), filepath.ToSlash(filepath.Join(repo, "pgxdriver")),
	)), 0o600))
	pgxSumBytes, err := os.ReadFile(filepath.Join(repo, "pgxdriver", "go.sum"))
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(compileDir, "go.sum"), pgxSumBytes, 0o600))

	buildCmd := exec.CommandContext(ctx, "go", "build", "-mod=mod", "./...")
	buildCmd.Dir = compileDir
	buildCmd.Env = append(os.Environ(), "GOWORK=off")
	var buildOut bytes.Buffer
	buildCmd.Stdout = &buildOut
	buildCmd.Stderr = &buildOut
	require.NoError(t, buildCmd.Run(), "docs/CHOOSING-AN-API.md starter failed to compile:\n%s", buildOut.String())

	// 2. Run the same starter against an isolated disposable PostgreSQL schema.
	sqlDB, err := sql.Open("postgres", dsn)
	require.NoError(t, err)
	t.Cleanup(func() { require.NoError(t, sqlDB.Close()) })

	suffix := time.Now().UnixNano()
	schema := fmt.Sprintf("tabula_starter_%d", suffix)
	role := fmt.Sprintf("tabula_starter_role_%d", suffix)
	execSQL := func(q string) {
		t.Helper()
		_, err := sqlDB.ExecContext(ctx, q)
		require.NoError(t, err, q)
	}
	execSQL("CREATE ROLE " + role + " NOLOGIN NOBYPASSRLS")
	t.Cleanup(func() { _, _ = sqlDB.Exec("DROP ROLE IF EXISTS " + role) })
	execSQL("CREATE SCHEMA " + schema)
	t.Cleanup(func() { _, _ = sqlDB.Exec("DROP SCHEMA IF EXISTS " + schema + " CASCADE") })
	execSQL(`CREATE TABLE ` + schema + `.items (
		id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		scope_id bigint NOT NULL,
		code text NOT NULL,
		name text NOT NULL,
		version integer NOT NULL DEFAULT 1
	)`)
	execSQL("GRANT USAGE ON SCHEMA " + schema + " TO " + role)
	execSQL("GRANT SELECT, INSERT, UPDATE ON " + schema + ".items TO " + role)

	isolatedSrc := strings.ReplaceAll(starterSrc, "public.items", schema+".items")
	require.NoError(t, os.WriteFile(filepath.Join(compileDir, "db", "db.go"), []byte(isolatedSrc), 0o600))
	const runnerMain = `package main

import (
	"context"
	"fmt"
	"os"

	"example.org/choosingapi/db"
	"github.com/0xJean/tabula/pgxdriver"
	"github.com/jackc/pgx/v5/pgxpool"
)

func main() {
	ctx := context.Background()
	pool, err := pgxpool.New(ctx, os.Getenv("STARTER_DSN"))
	if err != nil {
		panic(err)
	}
	defer pool.Close()

	role := os.Getenv("STARTER_ROLE")
	if err := db.VerifyAtStartup(ctx, pool, role); err != nil {
		panic(fmt.Errorf("VerifyAtStartup: %w", err))
	}
	runner, err := db.NewRunner(pool, role)
	if err != nil {
		panic(err)
	}
	scope := db.ScopeID(7)
	err = runner.Within(ctx, scope, func(ctx context.Context, s *pgxdriver.Session[db.ScopeID]) error {
		item := db.Item{ScopeID: scope, Code: "X-1", Name: "Sample", Version: 1}
		if err := db.Items.Bind(s).Insert(ctx, &item); err != nil {
			return err
		}
		got, err := db.FindItemByCode.Bind(s).One(ctx, db.CodeArgs{Code: "X-1"})
		if err != nil {
			return err
		}
		if got.ID != item.ID || got.ScopeID != scope || got.Name != "Sample" || got.Version != 1 {
			return fmt.Errorf("unexpected row: %+v", got)
		}
		return nil
	})
	if err != nil {
		panic(err)
	}
}
`
	require.NoError(t, os.WriteFile(filepath.Join(compileDir, "main.go"), []byte(runnerMain), 0o600))

	runCmd := exec.CommandContext(ctx, "go", "run", "-mod=mod", ".")
	runCmd.Dir = compileDir
	runCmd.Env = append(os.Environ(), "GOWORK=off", "STARTER_DSN="+dsn, "STARTER_ROLE="+role)
	var runOut bytes.Buffer
	runCmd.Stdout = &runOut
	runCmd.Stderr = &runOut
	require.NoError(t, runCmd.Run(), "docs/CHOOSING-AN-API.md starter failed at runtime:\n%s", runOut.String())
}
